\set ON_ERROR_STOP on
BEGIN READ ONLY;
SELECT json_build_object('section','identity','database',current_database(),'user',current_user,'host',host(inet_server_addr()),'port',inet_server_port(),'readOnly',current_setting('transaction_read_only'),'observedAt',current_timestamp);
SELECT json_build_object('section','database','data',json_agg(x)) FROM (SELECT datname,pg_get_userbyid(datdba) AS owner,datacl FROM pg_database WHERE datname=current_database()) x;
SELECT json_build_object('section','schemas','data',json_agg(x)) FROM (SELECT nspname,pg_get_userbyid(nspowner) AS owner,nspacl FROM pg_namespace WHERE nspname='public') x;
SELECT json_build_object('section','tables','data',json_agg(x)) FROM (SELECT relname,pg_get_userbyid(relowner) AS owner,relrowsecurity,relforcerowsecurity FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r' ORDER BY relname) x;
SELECT json_build_object('section','policies','data',json_agg(x)) FROM (SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' ORDER BY tablename,policyname) x;
SELECT json_build_object('section','indexes','data',json_agg(x)) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' ORDER BY tablename,indexname) x;
SELECT json_build_object('section','constraints','data',json_agg(x)) FROM (SELECT conrelid::regclass::text AS table_name,conname,contype,convalidated,pg_get_constraintdef(oid) AS definition FROM pg_constraint WHERE connamespace='public'::regnamespace ORDER BY conrelid::regclass::text,conname) x;
SELECT json_build_object('section','triggers','data',json_agg(x)) FROM (SELECT tgrelid::regclass::text AS table_name,tgname,tgenabled,pg_get_triggerdef(oid) AS definition FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace) AND NOT tgisinternal ORDER BY tgrelid::regclass::text,tgname) x;
SELECT json_build_object('section','functions','data',json_agg(x)) FROM (SELECT p.proname,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,pg_get_function_identity_arguments(p.oid) AS arguments,md5(pg_get_functiondef(p.oid)) AS definition_md5 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace ORDER BY p.proname,arguments) x;
SELECT json_build_object('section','enums','data',json_agg(x)) FROM (SELECT t.typname,array_agg(e.enumlabel ORDER BY e.enumsortorder) AS labels FROM pg_type t JOIN pg_enum e ON e.enumtypid=t.oid WHERE t.typnamespace='public'::regnamespace GROUP BY t.typname ORDER BY t.typname) x;
SELECT json_build_object('section','app_permissions','data',json_agg(x)) FROM (SELECT tablename,has_table_privilege('asistencia_app',quote_ident(tablename),'SELECT') AS sel,has_table_privilege('asistencia_app',quote_ident(tablename),'INSERT') AS ins,has_table_privilege('asistencia_app',quote_ident(tablename),'UPDATE') AS upd,has_table_privilege('asistencia_app',quote_ident(tablename),'DELETE') AS del,has_table_privilege('asistencia_app',quote_ident(tablename),'TRUNCATE') AS trunc,has_table_privilege('asistencia_app',quote_ident(tablename),'TRIGGER') AS trig FROM pg_tables WHERE schemaname='public' ORDER BY tablename) x;
SELECT json_build_object('section','app_column_updates','data',json_agg(x)) FROM (SELECT c.relname,a.attname,has_column_privilege('asistencia_app',c.oid,a.attnum,'UPDATE') AS allowed FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum) x;
SELECT json_build_object('section','role_permissions','data',json_agg(x)) FROM (SELECT rolname,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,has_database_privilege(rolname,current_database(),'CONNECT') AS connect,has_database_privilege(rolname,current_database(),'CREATE') AS dbcreate,has_schema_privilege(rolname,'public','USAGE') AS usage,has_schema_privilege(rolname,'public','CREATE') AS schemacreate FROM pg_roles WHERE rolname IN ('asistencia_migrator','asistencia_app') ORDER BY rolname) x;
-- Solo genera SELECT sobre nombres de catálogo con quoting de identificadores.
SELECT format('SELECT json_build_object(''section'',''count'',''table'',%L,''rows'',count(*)) FROM public.%I;',tablename,tablename) FROM pg_tables WHERE schemaname='public' ORDER BY tablename
\gexec
SELECT 'SELECT json_build_object(''section'',''migrations'',''data'',json_agg(x)) FROM (SELECT migration_name,checksum,finished_at,rolled_back_at,applied_steps_count FROM public._prisma_migrations ORDER BY migration_name) x;' WHERE to_regclass('public._prisma_migrations') IS NOT NULL
\gexec
COMMIT;
